\label{lem:nearcluster}
Let $K$ be a set of at least three bodies, pairwise joined by $zw$-edges, and let $X\notin K$ have no stroke to $K$. In each colour, say $z$, exactly one of the following holds: all $\zeta_{Xt}$, $t\in K$, are equal and less than $1$ \textup{(}$X$ is $z$-far\textup{)}; or all $\zeta_{Xt}\ge1$, at most one of them is larger than $1$ \textup{(}$X$ is $z$-near\textup{)}. The body $X$ is not near in both colours. With $\bar\omega<1$ the common far $w$-exponent and $s$ the exceptional $\zeta$, the possible modes are therefore:
\begin{itemize}
\item \textup{F}: $x_{Xt}=c<1$ for all $t$;
\item \textup{Z1}: $x_{Xt}=\frac{1+\bar\omega}2$ for all $t$;
\item \textup{Zs}$_{t_0}$: $x_{Xt_0}=\frac{s+\bar\omega}2$ and $x_{Xt}=\frac{1+\bar\omega}2$ for $t\ne t_0$, with $s>1$;
\item \textup{W1} and \textup{Ws}$_{t_0}$: the same with the colours exchanged.
\end{itemize} The parameters satisfy $s<2$, $s+\bar\omega<2$, $2s+\bar\omega<3$ and $2s+3\bar\omega<5$.

\label{lem:zwK4}
Suppose $\{kl:x_{kl}(P)=1\}=\mathrm{tri}(Q_j)$, and put $Q=Q_j$. Exactly one of the following holds, possibly after exchanging the colours.
\begin{enumerate}[label=\textup{(\Alph*)}]
\item $\alpha_i=\alpha$ and $\beta_i=\beta$ for all $i\in Q$, with $\alpha,\beta\le\frac12$, and $x_{ij}=c:=\alpha+\beta$ for all $i\in Q$, $0\le c<1$. So $x(P)=\mathsf{u}_c(j)$, and no stroke meets $j$.
\item There is a unique $k\in Q$ with $\alpha_k>\frac12$. Put $a=2\alpha_k$. Then $1<a\le2$, $\alpha_i=\frac12$ for $i\ne k$, $\beta_i=-\frac a2$ for all $i\in Q$, $x_{kj}=0$ and $x_{ij}=\frac{1-a}2$ for $i\ne k$, that is, $x(P)=\sigma_k(j)(a-1)$. If $a<2$, no stroke meets $j$. If $a=2$, the only stroke at $j$ is the $w$-stroke $kj$, and $kj$ is a maximal $w$-edge.
\end{enumerate}

\label{lem:lex}
Let $G_1,\dots,G_M$ be finite subsets of $\mathbb{Q}^{10}$, let $l_1,\dots,l_r\in\mathbb{Q}^{10}$, and let $I_1\cup\dots\cup I_r=\{1,\dots,M\}$ be a partition such that for every $i$:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $l_i\cdot v\ge0$ for every $v\in G_j$ and every $j\in I_i\cup I_{i+1}\cup\dots\cup I_r$;
\item for every $j\in I_i$ there is $v\in G_j$ with $l_i\cdot v>0$.
\end{enumerate}
Then $0$ is not a positive combination of $N\ge1$ points of $\bigcup_j\operatorname{relint}\operatorname{conv}(G_j)$.

\label{rem:hulls}
We use three D5 hulls of \S\ref{ss:d5}:
\begin{enumerate}[label=(\roman*)]
\item $V_2^{\mathrm w}$, valid at all positive masses;
\item $V_2\subseteqV_2^{\mathrm w}$, valid when $m_o\ne m_a+m_b$ for every $o$ in each triangle $T=\{o,a,b\}$ with $\mathsf{E}(T)\in S(m)$;
\item $V_N\subseteqV_2$, valid at the mass points described in \S\ref{ss:d5}.
\end{enumerate}
Each of them contains the projection of its model (Theorem~\ref{thm:hulls} and Lemma~\ref{lem:infty}). We apply each certificate below that uses $V_N$ only where $V_N$ is valid (checked in \S\ref{sec:verification}).

\label{lem:identities}
Suppose that $F(\tau,y):=V(\tau^{2e}y)=\sum_{n\ge0}\tau^{n-2}V_n(y)$, with $V_n$ holomorphic near $\bar y$ and the series convergent for $y$ near $\bar y$ and small $\tau\ne0$. Then $\nabla_yF(\tau,y(\tau))=0$, and for every $q\in\mathbb{Q}$ with $q\ne2$,
\begin{equation}\label{eq:qid}
\sum_{n\ge1}n\,\big[V_n(y(\tau))\big]_{q-n}=0 .
\end{equation}

\label{lem:d15lead}
\begin{enumerate}[label=\textup{(\alph*)}]
\item The cluster coefficients $(\hat z_i,\hat w_i)_{i\in Q'}$, with $\hat z_k=\hat w_k=0$, and $(\hat p_{il})_{i,l\in Q}$ solve $\mathrm{K15}(m_Q,k)$ with $c=-m_j\hat w_j/M$.
\item $\sum_{i\in Q'}m_i\hat z_i=0$.
\item $\hat p_{ij}^2\,\hat z_i\,(-\hat w_j)=1$ for $i\in Q'$.
\end{enumerate}

\label{lem:d15expansion}
At a place of type $\mathsf{b}_k(j)$, $F(\tau,y)=\sum_{n\ge0}\tau^{n-2}V_n(y)$ with
\begin{align*}
V_0&=U_Q(y)-\frac{m_j\,y_{v_j}}{2M}\sum_{i\in Q'}m_iy_{u_i}, \qquad V_1=V_4=0,\qquad V_2=f(\Pi),\\
V_3&=m_j\sum_{i\in Q'}m_i\,(-y_{u_i}y_{v_j})^{-1/2},\qquad V_5=\frac{m_j\,y_{u_j}}{2}\sum_{i\in Q'}m_i\,\frac{(-y_{u_i}y_{v_j})^{-1/2}}{y_{u_i}},
\end{align*}
where $U_Q$ is the potential of the cluster, $\Pi=y_{u_j}y_{v_j}$, $f(\Pi)=m_jm_k\Pi^{-1/2}+\frac{m_jM_Q}{2M}\Pi$, and the square roots are the branches of the $p_{il}$ at $P$. The coordinate $y_{u_j}$ occurs only in $V_2$ and in the $V_n$ with $n\ge5$.

The $y_{u_j}$-component of $\tau^2\nabla_yF(\tau,y(\tau))=0$ reads $y_{v_j}f'(\Pi)+O(\tau^3)=0$, by Lemma~\ref{lem:d15expansion}. At $\tau=0$ this is $f'(\bar\Pi)=0$, i.e.\ $\hat p_{kj}^3=\bar\Pi^{-3/2}=M_Q/(m_kM)$. Since $f''(\bar\Pi)=\frac34m_jm_k\bar\Pi^{-5/2}\neq0$, $f'(\Pi(\tau))=O(\tau^3)$ gives $\Pi(\tau)-\bar\Pi=O(\tau^3)$. Hence $f(\Pi(\tau))-f(\bar\Pi)=O(\tau^6)$ and
\begin{equation}\label{eq:V2flat}
\big[V_2(y(\tau))\big]_r=0\qquad(0<r<6).
\end{equation}
Now \eqref{eq:qid} with $q=3$ reads $[V_1]_2+2[V_2]_1+3V_3(\bar y)=0$. Since the first two terms vanish, $V_3(\bar y)=m_j\sum_im_i\hat p_{ij}=0$.

\label{thm:order5}
Let the masses satisfy $m_i\ne0$, $M\ne0$ and $M_Q\ne0$, and let $P$ be a singular place of type $\mathsf{b}_k(j)$.
\begin{enumerate}[label=\textup{(\alph*)}]
\item If the leading cluster configuration is nondegenerate, then $\sum_{i\in Q'}m_ix_i^3=0$.
\item If it has corank one, then $\kappa_3$ vanishes on $\ker H$.
\end{enumerate}

We fix an outer body $a$. By the freedom described in \S\ref{ss:expansion} we may assume $y_{v_j}(\tau)\equiv\hat w_j$ and $y_{u_a}(\tau)\equiv\hat z_a$: the conditions are $\mu^{-1}\varphi^4y_{v_j}=\hat w_j$ and $\mu\varphi^{-2}y_{u_a}=\hat z_a$, which determine $\varphi^2$ and then $\mu$. Write $y(\tau)-\bar y=(\delta(\tau),\delta_{u_j}(\tau))$ with $\delta$ the cluster part, so that $\delta_{u_a}=0$. Let $S=\{\xi\in\mathbb{C}^6:\xi_{u_a}=0\}$. Since $X\in\ker H$ and $X_{u_a}=\hat z_a\ne0$, the kernel of the restriction of the form $H$ to $S$ is $K_S=\ker H\cap S$, of dimension equal to the corank. Choose a complement $W$ of $K_S$ in $S$ and write $\delta=\xi(\tau)+\eta(\tau)$ with $\xi(\tau)\in K_S$, $\eta(\tau)\in W$. Let $\alpha$ be the valuation of $\xi(\tau)$ ($\alpha=\infty$ if $\xi\equiv0$).

By Lemmas~\ref{lem:identities} and \ref{lem:d15expansion}, the cluster components of $\tau^2\nabla_yF=0$ are $\nabla\Psi_c(\bar y+\delta)+\tau^3\nabla V_3(y)+O(\tau^5)=0$, because $V_2$ does not involve the cluster and $V_0=\Psi_c$ along the normalized place. Taylor expansion gives $H\delta+R(\delta)+\tau^3\nabla V_3(y)+O(\tau^5)=0$ with $R(\delta)=O(|\delta|^2)$. Taking the components in $S^*$ and using that $H|_S$ maps $W$ isomorphically onto its image, the valuation of $\eta$ is at least the minimum of $3$, $2\alpha$, $\alpha+\operatorname{val}\eta$ and $2\operatorname{val}\eta$. Hence
\begin{equation}\label{eq:etaval}
\operatorname{val}\eta\ge\min(3,2\alpha).
\end{equation}
Pairing the same equation with $\xi_0\in K_S$ and using $\xi_0^{\mathsf T}H=0$ gives
\begin{equation}\label{eq:bif}
\xi_0\cdot R(\delta)+\tau^3\,\xi_0\cdot\nabla V_3(y(\tau))+O(\tau^5)=0 .
\end{equation}
Since $y_{v_j}$ is constant, $V_3(y(\tau))=V_3(\bar y)+\kappa_3(\delta)+O(|\delta|^2)$ with $V_3(\bar y)=0$.

\eqref{eq:qid} with $q=5$ reads $[V_1]_4+2[V_2]_3+3[V_3]_2+4[V_4]_1+5V_5(\bar y)=0$. By \eqref{eq:V2flat} this becomes
\begin{equation}\label{eq:q5}
3\big[V_3(y(\tau))\big]_2+5V_5(\bar y)=0 .
\end{equation}

(a) Since $K_S=0$ in this case, $\delta=\eta$ has valuation at least $3$ by \eqref{eq:etaval}. Hence $[V_3(y(\tau))]_2=0$. Then \eqref{eq:q5} gives $V_5(\bar y)=0$, i.e.\ $\sum m_ix_i^3=0$.

(b) Here $K_S=\mathbb{C}\xi_0$ and $\xi(\tau)=a(\tau)\xi_0$ with $a(\tau)=a_\alpha\tau^\alpha+\dots$, $a_\alpha\ne0$. Suppose $\kappa_3(\xi_0)\ne0$. If $\alpha<2$, we apply \eqref{eq:qid} with $q=3+\alpha$: the terms $n=1,4$ vanish, the term $n=2$ is $2[V_2]_{1+\alpha}=0$ by \eqref{eq:V2flat}, and the terms $n\ge5$ have negative index. This leaves $[V_3(y(\tau))]_\alpha=0$. But by \eqref{eq:etaval} the valuations of $\eta$ and of $|\delta|^2$ exceed $\alpha$. Therefore $[V_3(y(\tau))]_\alpha=a_\alpha\kappa_3(\xi_0)\ne0$, a contradiction. Hence $\alpha\ge2$. Then $\operatorname{val}\eta\ge3$ and $\operatorname{val} R(\delta)\ge4$. The coefficient of $\tau^3$ in \eqref{eq:bif} is then $\xi_0\cdot\nabla V_3(\bar y)=\kappa_3(\xi_0)$, which must vanish, again a contradiction. Thus $\kappa_3(\xi_0)=0$. As $\kappa_3(X)=0$ and $\ker H=\mathbb{C} X\oplus\mathbb{C}\xi_0$, the form $\kappa_3$ vanishes on $\ker H$.

\label{thm:residual}
Let the outer masses be positive and $m_k\ne0$, let $(\hat z,\hat w)$ solve $\mathrm{K15}(m_Q,k)$ with body $k$ at the origin, suppose $\sum_{i\in Q'}m_ix_i=0$ with $x_i^2=1/\hat z_i$, and let $\xi\in\ker H\setminus\mathbb{C} X$ satisfy $\sum_{i\in Q'}m_ix_i^3\xi_{u_i}=0$. Then one of the following holds:
\begin{enumerate}[label=\textup{(\roman*)}]
\item the outer masses are equal and $\{\hat z_i\}=\lambda\{1,\mathrm{j},\mathrm{j}^2\}$;
\item \textup{(G2)} $\ker L_q=\mathbb{C}\hat z$ and $L_{q\varrho}\hat z=0$;
\item \textup{(G1)} $L_q=\sigma\,\tilde m\tilde m^{\mathsf T}$ for some $\sigma$, and $\operatorname{rank} L_{q\varrho}=1$.
\end{enumerate}

\label{lem:d14exp}
At a place of type $\sigma_k(j)(t)$, with $\Pi$, $f$ and $U_Q$ as in Lemma~\ref{lem:d15expansion},
\begin{equation}\label{eq:d14F}
F(\tau,y)=\tau^{-2}U_Q(y)+\tau^{2-2\sigma}\Gamma(y)+f(\Pi)+\sum_{n\ge0}\tau^{(2n+1)(\sigma-1)}B_n(y)+R(\tau,y),
\end{equation}
where $\Gamma=-\frac{m_j}{2M}y_{v_j}\psi$, $B_n=\binom{2n}{n}4^{-n}m_jw\,y_{u_j}^nS_{2n+1}$, and $R$ is a convergent sum of terms $\tau^LR_L(y)$ with $L\ge4$. The coordinate $y_{u_j}$ occurs only in $f$, in the $B_n$ with $n\ge1$ and in $R$, and the coordinates $y_{v_i}$, $i\in Q'$, occur only in $U_Q$ and in $R$.

\label{lem:d14energy}
At a place of type $\sigma_k(j)(t)$:
\begin{enumerate}[label=\textup{(\alph*)}]
\item $U_Q(y(\tau))=O(\tau^6)$;
\item $[B_0(y(\tau))]_r=0$ for $0\le r<2\sigma-2$; in particular $\sum_{i\in Q'}m_ix_i=0$, and the leading cluster configuration satisfies $\mathrm{X3}_k$ and has a bad shape;
\item $B_1(\bar y)=-\frac35\,[B_0(y(\tau))]_{2\sigma-2}$.
\end{enumerate}

\label{lem:inversion}
\begin{enumerate}[label=\textup{(\alph*)}]
\item The numbers $(z'_a-z'_b)(w'_a-w'_b)$, $(z'_b-z'_c)(w'_b-w'_c)$ and $(z'_c-z'_a)(w'_c-w'_a)$ are a common nonzero factor times the products $\eta_{ab}\eta_{ck}$, $\eta_{bc}\eta_{ak}$ and $\eta_{ca}\eta_{bk}$ of the pattern.
\item There is $C\ne0$ with $m_i=C\,u'_i/p_{ik}$ for $i\in Q'$.
\end{enumerate}

\label{lem:d9exp}
At a place of type $\mathsf{n}(\{1,2,3\};14,25)$, the function $F(\tau,y)=\sum_{n\ge0}\tau^{n-2}V_n(y)$ satisfies the hypothesis of Lemma~\ref{lem:identities} in the coordinates above, with $V_1=0$ and
\begin{align*}
V_0&=U_T+\tfrac\nu2\,\Omega\,L(u),\\
V_2&=m_1m_4(u_{41}\Omega)^{-1/2}+m_2m_5(u_{52}\Omega)^{-1/2}+m_4m_5(u_{12}v_{45})^{-1/2}\\
&\qquad+\tfrac{\nu_{45}}2\,u_{12}v_{45}+\tfrac\nu2\,\Omega\,\frac{m_4u_{41}+m_5u_{52}}{m_4+m_5},\\
V_3&=m_1m_5(-u_{12}\Omega)^{-1/2}+m_2m_4(u_{12}\Omega)^{-1/2}+m_3m_4(u_1\Omega)^{-1/2}+m_3m_5(u_2\Omega)^{-1/2},
\end{align*}
where the square roots are the branches of the $p_{kl}$ at $P$. The coefficients $V_0$ and $V_3$ do not depend on the fine coordinates.

Suppose that $P$ has diagram~$9$, with the labelling above. On the pairs $kl=15,24,34,35$, Lemma~\ref{lem:d9exp} gives $\hat p_{kl}=(\bar z_{kl}\bar w_{kl})^{-1/2}$ at $\bar y$, with $\bar w_{kl}=-\bar\Omega$. By Lemma~\ref{lem:d9lead}(b), $(m_4+m_5)\bar z_{kl}=\tilde\rho_{kl}\hat z_{12}$ at $\bar y$, where $\tilde\rho_{15}=m_4+m_5$, $\tilde\rho_{24}=-(m_4+m_5)$, $\tilde\rho_{34}=\rho_{31}$ and $\tilde\rho_{35}=\rho_{32}$. Let $K$ be a square root of $-(m_4+m_5)/(\hat z_{12}\bar\Omega)$. Then $\hat p_{kl}=\pm K\tilde\rho_{kl}^{-1/2}$ if $\tilde\rho_{kl}>0$, and $\hat p_{kl}=\pm iK|\tilde\rho_{kl}|^{-1/2}$ if $\tilde\rho_{kl}<0$. So Proposition~\ref{prop:d9cross} says that two sums of real numbers $\pm m_km_l|\tilde\rho_{kl}|^{-1/2}$ vanish, one over the pairs with $\tilde\rho_{kl}>0$ and one over the pairs with $\tilde\rho_{kl}<0$. Each sum therefore has at least two terms. The pair $15$ is in the first sum, $24$ is in the second, and $\rho_{31}<\rho_{32}$. Hence $\rho_{31}<0<\rho_{32}$, the first sum is over $15$, $35$ and the second over $24$, $34$, and they vanish only if
\begin{equation}\label{eq:C12}
m_1^2\rho_{32}=m_3^2(m_4+m_5),\qquad m_2^2\rho_{31}=-m_3^2(m_4+m_5).
\end{equation}
Let $\alpha=\hat p_{12}/\hat p_{23}$ and $\beta=\hat p_{12}/\hat p_{31}$. By Lemma~\ref{lem:d9lead}(c), $\hat p_{kl}^3\hat z_{kl}$ is $\kappa m_3$, $\kappa m_1$, $\kappa m_2$ for $kl=12,23,31$. By Lemma~\ref{lem:d9lead}(b), $(m_4+m_5)\hat z_{23}=-\rho_{32}\hat z_{12}$ and $(m_4+m_5)\hat z_{31}=\rho_{31}\hat z_{12}$. With Lemma~\ref{lem:d9lead}(d) these relations give
\begin{gather*}
m_1(m_4+m_5)\alpha^3=-m_3\rho_{32}=m_1m_5-m_2m_4-m_3m_4,\\
m_2(m_4+m_5)\beta^3=m_3\rho_{31}=m_2m_4-m_1m_5-m_3m_5,\\
m_1m_3\alpha+m_2m_3\beta+m_1m_2\alpha\beta=\alpha\beta\,U_T(\bar y_c)/\hat p_{12}=0.
\end{gather*}
By \eqref{eq:C12}, $\alpha^3=-(m_3/m_1)^3$ and $\beta^3=-(m_3/m_2)^3$. So $\alpha=-\eta m_3/m_1$ and $\beta=-\eta'm_3/m_2$ with $\eta^3=\eta'^3=1$. The third relation becomes $m_3^2(\eta\eta'-\eta-\eta')=0$, that is, $(\eta-1)(\eta'-1)=1$. This is impossible, because $|\eta-1|$ and $|\eta'-1|$ are $0$ or $\sqrt3$.

The last statement follows, since Theorem~\ref{thm:types} places the type of a singular place in a piece of its own diagram.

\label{thm:KA}
Let $\ell$ be a prime and $\bar\theta\in\mathbb F_\ell$ such that:
\begin{enumerate}[label=(P\arabic*)]
\item $\ell$ divides neither the leading coefficient of $f$ nor a denominator of a coefficient of a $g_i$; $\bar f=f\bmod\ell$ is squarefree of degree $\deg f$, and $\bar f(\bar\theta)=0$;
\item $\bar\mu_i\ne0$ for $i\in Q$, $\sum_i\bar\mu_i\ne0$, and $c_{\nu,a}(\bar\mu)\ne0$ for every generator and every $a\in A_\nu$;
\end{enumerate}
\begin{enumerate}[label=(\Alph*)]
\item the ideal of $\mathbb F_\ell[\xi_0,\xi]$ generated by $\bar F_1,\dots,\bar F_N$ and $\xi_0\xi_1\cdots\xi_N-1$ is the unit ideal;
\item for every cell $\sigma$, the ideal generated by $\mathrm{in}_\sigma\bar F_1,\dots,\mathrm{in}_\sigma\bar F_N$ and $\xi_0\xi_1\cdots\xi_N-1$ is the unit ideal.
\end{enumerate}
Then for every root $\theta\in\mathbb{C}$ of $f$ the masses $g_i(\theta)$ and their sum are nonzero, and $\mathrm{K14}(\mu(\theta))$, respectively $\mathrm{K15}(\mu(\theta),k)$, has no solution.

\label{thm:KApar}
Let $\ell$ be a prime and $\bar\theta\in\mathbb F_\ell$ such that $\ell$ does not divide the leading coefficient of $f$, $\bar f$ is squarefree of degree $\deg f$, $\bar f(\bar\theta)=0$, and $e_{\nu,a}(\bar\theta)\ne0$ for all $\nu$ and $a$.
\begin{enumerate}[label=(\alph*)]
\item If $1$ lies in the ideal of $\mathbb F_\ell[\xi_0,\xi,s]$ generated by $\bar G_1,\dots,\bar G_n$ and $\xi_0\xi_1\cdots\xi_Ns-1$, and in the corresponding ideal of the initial systems of every cell, then for every root $\theta$ of $f$ and every $s\in\mathbb{C}^*$ the system $G(\cdot,s)$ has no zero in $(\mathbb{C}^*)^N$.
\item Let $h\in\mathbb{Z}[s]$ with $\bar h=h\bmod\ell$ of degree $\deg h$ and $\bar h(0)\ne0$. If over $\bar{\mathbb F}_\ell$ the full system, together with $\bar h(s)=0$, has no zero with all coordinates nonzero, and the same holds for the initial system of every cell whose relative interior contains a point with $s$-coordinate $0$, then for every root $\theta$ of $f$ and every root $s_0$ of $h$ the system $G(\cdot,s_0)$ has no zero in $(\mathbb{C}^*)^N$.
\end{enumerate}

\label{def:Kcert}
Let $m\in(\mathbb{R}_{>0})^5$ and $T\subseteq\{1,\dots,5\}$. The point $m$ is \emph{K-certified with transversal $T$} if
\begin{enumerate}[label=(\roman*)]
\item for every $j\in T$, $\mathrm{K14}(m_{Q_j})$ has no solution; and
